import{_ as i}from"./chunks/home.KfBfMT0S.js";import{_ as t,a as e,b as a,c as o,d as p,e as l}from"./chunks/languages.BS_4zFMB.js";import{_ as s}from"./chunks/kefu-chat.CQaKJK-O.js";import{_ as n,o as d,c as g,a2 as c}from"./chunks/framework.DDY-poMm.js";const T=JSON.parse('{"title":"移动端 App","description":"","frontmatter":{},"headers":[],"relativePath":"zh/app/overview.md","filePath":"zh/app/overview.md","lastUpdated":1790683574000}'),x={name:"zh/app/overview.md"};function h(f,r,m,b,u,v){return d(),g("div",null,[...r[0]||(r[0]=[c('<h1 id="移动端-app" tabindex="-1">移动端 App <a class="header-anchor" href="#移动端-app" aria-label="Permalink to &quot;移动端 App&quot;">​</a></h1><p>RWABTX 是平台的<strong>原生双端 App（Android / iOS）</strong>。</p><p>我们<strong>没有采用&quot;网页套壳&quot;的做法</strong>，而是用 Flutter 跨平台原生技术路线，从登录、行情、K 线、下单、结算到资产、充提，全部以原生页面重写。相比套壳方案，它带来三点确定性的差异：<strong>启动更快、操作跟手、可正式上架应用商店</strong>。</p><p>App 与网页端共用同一套后端与账户体系——<strong>同一个账号，网页与 App 数据完全一致，可随时互相切换</strong>。</p><h2 id="界面一览" tabindex="-1">界面一览 <a class="header-anchor" href="#界面一览" aria-label="Permalink to &quot;界面一览&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+i+'" alt="App 首页" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>首页</b><br>资产总览与快捷入口，宫格内容由后台配置 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+t+'" alt="K 线图表" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>K 线图表</b><br>TradingView 专业图表，多周期与指标齐全 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+e+'" alt="秒合约" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>秒合约</b><br>周期与结算参数由平台在后台配置 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="TradFi 传统金融标的" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>TradFi</b><br>外汇等传统标的，休市期间明确提示且不可下单 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+o+'" alt="资产总览" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>资产总览</b><br>平台 / 理财 / 合约分账户，持仓币种一目了然 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+p+'" alt="充值" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>充值</b><br>按币种标明网络，并直接提示&quot;充错链无法找回&quot; </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+l+'" alt="多语言" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>多语言</b><br>内置 7 种语言，可用范围由后台控制 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+s+'" alt="在线客服" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>在线客服</b><br>App 内直接聊天，客服在 Telegram 接待，图文实时互通 </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">关于这些截图</p><p>均为 Android 正式签名包的<strong>真机实拍</strong>，非设计稿。其中的账户余额、行情价格、玩法参数均为<strong>演示环境的数据</strong>，不代表实际运营配置 —— 这些参数都由平台自行在后台设定。</p></div><h2 id="交易" tabindex="-1">交易 <a class="header-anchor" href="#交易" aria-label="Permalink to &quot;交易&quot;">​</a></h2><ul><li><strong>行情与 K 线</strong>：接入 TradingView 专业图表，多周期切换、指标齐全；行情价格实时推送</li><li><strong>秒合约</strong>：下单 → 倒计时 → 自动结算全链路原生。倒计时以服务端定盘时刻为唯一基准，所见即真实结算时点</li><li><strong>U 本位永续合约</strong>：划转、开仓、持仓、平仓完整闭环，市价/限价、盘口十档、实时盈亏一屏可见</li><li><strong>币币现货与闪兑</strong>：两种交易方式并行</li><li><strong>TradFi</strong>：外汇、商品、股票、指数等传统金融品类，与数字资产一致的交易体验</li></ul><h2 id="资产与资金" tabindex="-1">资产与资金 <a class="header-anchor" href="#资产与资金" aria-label="Permalink to &quot;资产与资金&quot;">​</a></h2><p>资产总览、账户分布（现货 / 合约 / 理财分账户一目了然）、划转、充值、提现、充提记录、资金流水，全部原生化。</p><p>充值页按币种正确标识 TRC20 / ERC20 / BEP20 等网络，从源头避免充错链。</p><h2 id="理财与增值" tabindex="-1">理财与增值 <a class="header-anchor" href="#理财与增值" aria-label="Permalink to &quot;理财与增值&quot;">​</a></h2><p>理财（三分区）、质押、助力贷、挖矿全部原生页面。申购（打新）的项目列表、认购、订单与状态流转全流程原生。跟单与带单同样支持。</p><h2 id="账户与安全" tabindex="-1">账户与安全 <a class="header-anchor" href="#账户与安全" aria-label="Permalink to &quot;账户与安全&quot;">​</a></h2><ul><li><strong>注册 / 登录 / 找回密码</strong>：App 端具备完整的独立注册能力，无需跳转网页</li><li>实名认证、邮箱认证、银行卡、条款协议、VIP 等级、<a href="/CoinExchange/zh/guide/customer-service">在线客服</a>全部原生化</li><li>网络层启用 HTTPS + HTTP/2；登录态失效即时识别并安全跳转</li></ul><h2 id="运营可配置" tabindex="-1">运营可配置 <a class="header-anchor" href="#运营可配置" aria-label="Permalink to &quot;运营可配置&quot;">​</a></h2><p>平台后台即可控制 App 的呈现，<strong>无需发版</strong>：</p><ul><li>底部导航 Tab、首页服务宫格、「我的」菜单、资产页 Tab 均由后台配置驱动</li><li>公告、帮助中心、下载中心、白皮书、推广中心内容后台可维护</li><li><strong>邀请码深链归因</strong>：用户通过推广链接安装 App 后，邀请关系自动带入，代理推广体系在 App 上完整延续</li></ul><h2 id="多语言" tabindex="-1">多语言 <a class="header-anchor" href="#多语言" aria-label="Permalink to &quot;多语言&quot;">​</a></h2><p>内置 <strong>7 种语言</strong>：简体中文、繁体中文、英语、日语、韩语、越南语、泰语。语言列表由后台控制，可按运营区域开关。</p><h2 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h2><p>App 会自动检测新版本并提示更新，用户可在 App 内完成下载与安装。详见<a href="/CoinExchange/zh/app/install">安装与更新</a>。</p><hr><div class="tip custom-block"><p class="custom-block-title">iOS</p><p>Android 与 iOS 为同一套原生工程，<strong>iOS 版使用您的苹果开发者证书签名后发布</strong>。</p></div>',25)])])}const P=n(x,[["render",h]]);export{T as __pageData,P as default};
